namespace sv_a25c0db6e1a54c1aa26a268fe27c6f66.Services;

/// <summary>
/// Scoped service that owns the selected warehouse and bridges updates
/// to the DI-registered CascadingValueSource so every [CascadingParameter]
/// subscriber re-renders automatically — even across render-mode boundaries.
/// </summary>
public class WarehouseState
{
    private readonly CascadingValueSource<WarehouseInfo> _cascadingSource;

    public WarehouseState(CascadingValueSource<WarehouseInfo> cascadingSource)
    {
        _cascadingSource = cascadingSource;
        Current = WarehouseInfo.Default;
    }

    public WarehouseInfo Current { get; private set; }

