        OnChange?.Invoke();
    }
}

namespace sv_a25c0db6e1a54c1aa26a268fe27c6f66.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Components call StartPolling/StopPolling to control the background timer.
/// All subscribers receive OnAlertCountChanged when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activePollers;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired from a background thread — subscribers must wrap
    /// StateHasChanged in InvokeAsync.
    /// </summary>
    public event Action? OnAlertCountChanged;

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Reference-counted: multiple components can request polling and
    /// the timer runs as long as at least one is active.
    /// </summary>
    public void StartPolling()
    {
        _activePollers++;
        if (_activePollers == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    public void StopPolling()
    {
        _activePollers = Math.Max(0, _activePollers - 1);
        if (_activePollers == 0)
        {
            CancelTimer();
        }
    }

    /// <summary>
    /// Fetch once immediately (e.g. on warehouse change) and notify all subscribers.
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire immediately on first poll.
        await RefreshAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                CurrentAlertCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
                OnAlertCountChanged?.Invoke();
            }
        }
        catch (OperationCanceledException) { }
    }

    private void CancelTimer()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelTimer();
    }
}

