@page "/dashboard"
@rendermode InteractiveServer

@using sv_a25c0db6e1a54c1aa26a268fe27c6f66.Services
@inject InventoryAlertService AlertService
@inject WarehouseState WarehouseState
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<CascadingValue Value="@_warehouse">
    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card">
                <div class="card-body text-center">
                    <h5 class="card-title">Current Warehouse</h5>
                    <p class="display-6">@WarehouseState.Current.Name</p>
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-body text-center">
                    <h5 class="card-title">Low-Stock Alerts</h5>
                    <p class="display-6">
                        @if (AlertService.CurrentAlertCount > 0)
                        {
                            <span class="text-danger">@AlertService.CurrentAlertCount items</span>
                        }
                        else
                        {
                            <span class="text-success">All clear</span>
                        }
                    </p>
                </div>
            </div>
        </div>

        <div class="col-md-4">
            <div class="card">
                <div class="card-body text-center">
                    <h5 class="card-title">Polling Status</h5>
                    <p class="display-6 text-info">Active</p>
                    <small class="text-muted">Refreshes every 10 seconds</small>
                </div>
            </div>
        </div>
    </div>
</CascadingValue>

@code {
    private WarehouseInfo? _warehouse;
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _warehouse = WarehouseState.Current;

        // Subscribe to alert changes (fires from background timer — use InvokeAsync).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes so we can re-poll immediately.
        _warehouseHandler = async () =>
        {
            _warehouse = WarehouseState.Current;
            await AlertService.RefreshAsync();
            await InvokeAsync(StateHasChanged);
        };
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling while the dashboard is visible.
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.StopPolling();
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

